  var TILE_NAMES = [
    'stone', 'dirt', 'grass_top', 'grass_side', 'cobblestone',
    'oak_planks', 'bedrock', 'sand', 'gravel', 'oak_log_top',
    'oak_log_side', 'leaves', 'water', 'glass', 'coal_ore',
    'iron_ore', 'gold_ore', 'diamond_ore', 'snow', 'snow_side',
    'sandstone', 'clay', 'bricks', 'bookshelf', 'glowstone',
    'dandelion', 'rose', 'tall_grass', 'birch_log_top', 'birch_log_side'
